mapper.select:
with slip as ( select a.slip_date ,a.slip_id ,b.acc_code ,c."name" as acc_name ,c.budget_code ,b.detail_id ,b.summary ,b.dr_cr ,coalesce(case when b.dr_cr = 'D' then b.amount end , 0) as d_amt ,coalesce(case when b.dr_cr = 'C' then b.amount end, 0) as c_amt ,d.amount from tb_slip_header a left outer join tb_slip_detail b on a.slip_id = b.slip_id left outer join tb_account_category c on b.acc_code = c.code left outer join tb_budget_category d on c.budget_code = d.code where 1=1 and #{start_date} <= a.slip_date and a.slip_date <= #{end_date}
and b.acc_code = #{acc_code}
order by a.slip_id, b.dr_cr desc ) select s.slip_date ,s.slip_id ,s.acc_code ,s.acc_name ,s.budget_code ,s.detail_id ,s.summary as description ,s.dr_cr ,s.d_amt as dr_amount ,s.c_amt as cr_amount ,case when s.dr_cr = 'C' then s.amount else s.d_amt end as finalBalance ,case when s.dr_cr = 'C' then s.c_amt + s.amount else 0 end as base_balance from slip s
